    final symbols = <MapSymbol>[];
    for (final name in orderedNames) {
      final resolution = names[name]!;
      if (resolution.kind == 'common' && !resolution.live)
        result.add(
          'discard ${resolution.definer} COMMON($name) ${resolution.size} gc',
